INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Clash of Magic', 'On the United Island of Magic, there is an Academy of Witchcraft and Wizardry. Students with magic powers, regardless of their ethnicity and background, can apply to this university. The acceptance rate is lower than Harvard. Once in, they will have the access to learn from the masters of Magic and train with other equally outstanding and magical peers. INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 96461 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;
