INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Roving in the Dark', 'Roving in the Dark is a cave exploration platformer set in 1996. You play as a bearded caver (known as "Local Spelunker") who is tasked with rescuing ill-equipped treasure-seekers while finding treasure, hidden there by a medieval thief, for the local museum. . Avoid slipping and falling into holes, getting hit by stones, getting super cooled, running out of batteries or being pushed by in by foreign cavers.' FROM games WHERE igdb_id = 106602 ON CONFLICT (game_id, language_code) DO NOTHING;
