INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bullets and More VR: BAM VR', 'Jump into a massive multiplayer experience with up to 12 players in about 20 different maps and various different game modes (Deathmatch, Team Deathmatch, Capture The Flag, Virus Infection, Gun Game and Classic Deathmatch). Enjoy an arsenal of more than 20 weapons featuring realistic weapon behaviour and support for attachments, silencers and even bipods. Furthermore also featuring singleplayer modes and a Scene Editor with Workshop support.' FROM games WHERE igdb_id = 31401 ON CONFLICT (game_id, language_code) DO NOTHING;
