INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('library-cross-toki-ga-kitara-kono-negai-wo', 267598, '2018-01-25', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co73y5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scomv5.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Library Cross: Toki ga Kitara, Kono Negai wo', 'Produced by otome game label Otomate, LibraryCross is a crazily huge crossover between many of the developer''s works, including Amnesia, Hakuoki, Norn9, Beast and Princess, Welcome to Fukujuro, and Yunohana SpRINGI. Featuring nine original characters, the heroine is a medical student who finds herself locked up in a mysterious place upon waking up. Having only a strange white book and a clock, she will have to choose between following the instructions in the book to escape, or to die in that room once the clock hits 13:00.' FROM games WHERE igdb_id = 267598 ON CONFLICT (game_id, language_code) DO NOTHING;
