INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Punch Perfect', 'Punch Perfect is a free memory and reaction boxing game now available to download on iOS and Android. In the game, players will be training with no-nonsense boxing coach Simon, throwing different punch combos at the pads on his hands by for example tapping to throw a jab or swiping to throw a hook. Learn, memorise and repeat the combos before coach Simon’s patience runs out, with combinations becoming increasingly difficult for the ultimate brain challenge!' FROM games WHERE igdb_id = 112426 ON CONFLICT (game_id, language_code) DO NOTHING;
