INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shape of America: Episode One', 'Shape of America is a story-driven, non-linear, turn-based role-playing game about politics. The story is set the United States in the late 1990s, you are a young man who unwittingly finds himself tied up in all the important economic and political changes of the period. Meet new people, make deals, invest in the stock market, give speeches, do everything to become president of U.S. and change the shape of America.' FROM games WHERE igdb_id = 76935 ON CONFLICT (game_id, language_code) DO NOTHING;
