INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Marius', 'Congratulations! Your application has been successful. We are delighted to invite you to be our first intern. But, there is something you should know. This is no ordinary library, and the books are not ordinary books. This is a library where books are keys to mystical realities. In between the dusty shelves, you will find a very special rabbit, with a very special gift. His name is Marius and this is the story of how he travels to new worlds, one book at a time.' FROM games WHERE igdb_id = 76368 ON CONFLICT (game_id, language_code) DO NOTHING;
