INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3D MiniGolf', 'Experience virtual but realistic mini-golf and master an entertaining match on over 54 challenging holes, 18 of which faithfully modelled after official courses in the real world. Three scenarios in glorious HD are waiting for the discerning mini-golf enthusiast: a lovely green park, a camping site in the mountains and a dreamy sandy beach. Use your profile to keep track of your statistics. Thanks to the integrated medal system you collect virtual rewards for your best matches.' FROM games WHERE igdb_id = 147887 ON CONFLICT (game_id, language_code) DO NOTHING;
