INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Disney Heroes: Battle Mode', 'Disney Heroes: Battle Mode is an action-packed mobile role-playing game that brings together beloved characters from Disney and Pixar universes. In the game, players assemble a team of iconic heroes like Mickey Mouse, Elsa, Buzz Lightyear, and more, each with unique abilities and skills. The gameplay revolves around strategic team-building and tactical combat as they engage in thrilling battles against waves of enemies and challenging bosses, unlocking and upgrading new heroes, customizing their abilities, and strengthening their team to take on even greater challenges.' FROM games WHERE igdb_id = 96138 ON CONFLICT (game_id, language_code) DO NOTHING;
