INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Settlers: History Edition', 'Haven''t you always wanted to be king? Indulge your fantasy in the world of The Settlers. You alone determine how your kingdom will be formed, how large it will be, whether to limit your ambitions to agriculture, breeding of stock, and fishing, or whether you want to start an industrial revolution. Turn back the clock 25 years and relive the fascination of this classic in gaming history!' FROM games WHERE igdb_id = 107232 ON CONFLICT (game_id, language_code) DO NOTHING;
