INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('lunch-break', 113892, '2018-09-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1ijx.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5u7j.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lunch Break', 'Lunch Break is an retro arcade-style game. The player’s character, Chris, is trying to eat his picnic, but various critters and hazards are out to ruin it. There are 4 onscreen buttons to help Chris avoid or fend off pests; kick, swat, duck, and switch sides of the bench. Chris will lose enjoyment for each time his lunch is interrupted, and if his enjoyment runs out completely then his lunch break is ruined and it’s game over. Each of the game’s levels have a time limit; if the timer reaches zero before Chris’s enjoyment does, then the game advances to the next level and Chris’s enjoyment is replenished. There are many different levels which gradually get more difficult and feature different hazards. Every forth level is a bonus round where you must make Chris frantically shovel food into his mouth while being careful to not accidentally eat a pigeon. Like the retro games which inspired it; the game is about score chasing and not about completion; it continues until the player loses. There is an online leaderboard for players to share and compare their high scores.' FROM games WHERE igdb_id = 113892 ON CONFLICT (game_id, language_code) DO NOTHING;
