INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Psycho Squirrels', 'Psycho Squirrels is a 2D platforming, puzzle game where players must navigate squirrels through a variety of stages to collect acorns before winter arrives. These city squirrels have been slacking off and aren''t prepared for winter. They need your help as they head out into the world in search of acorns. Get ready to get nuts!​- Help the squirrels collect enough acorns before winter arrives. - Use the local flora and fauna to guide your squirrels to their goals. - Navigate through 50 puzzling stages plus bonus stages.' FROM games WHERE igdb_id = 101260 ON CONFLICT (game_id, language_code) DO NOTHING;
