INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dungeon Stars', 'Use sword and spell to delve deep and battle through hordes of powerful enemies. Does the next room contain a healing fountain, a rare treasure, or the Toxic Ogre King? You need to keep on your toes as you face unknowns in every room. If you delve deep enough, you may face the legendary eater of light, the Conqueror Worm!' FROM games WHERE igdb_id = 96148 ON CONFLICT (game_id, language_code) DO NOTHING;
