INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mahjong Riichi Multiplayer', 'Japanese mahjong, also known as Riichi mahjong, is a 4 player tabletop game based on the chinese original mahjong. Compete against individuals from all over the world in the online multiplayer mode. Build sequences and tripplets within your hand and complete your hand faster than your opponents!' FROM games WHERE igdb_id = 373845 ON CONFLICT (game_id, language_code) DO NOTHING;
