INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asemblance Collection', 'This collection includes both the first episode of "Asemblance" and its follow-up "Asemblance: Oversight". The Asemblance series offers first-person exploration and puzzle-based gameplay, which puts you at the center of the story''s mystery. Through the use of an AI-guided memory machine you are able to visit simulations of recorded memories. The more you explore the memories, the deeper stories they tell.' FROM games WHERE igdb_id = 110582 ON CONFLICT (game_id, language_code) DO NOTHING;
