INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Angles', 'Angles is an Adventure game set in a Fantasy world based on Britain in the Dark Ages. It features many mythical creatures which have infested the lands outside the Village. You must Journey outside and gather your strength, earning Gold and upgrading your Character. Combat uses a point and click system with range restrictions on Melee weapons. The world is procedurally generated to offer unique hunting grounds when out on an adventure. It features Retro styled 2D Animations in a 3D world, using fixed perspective.' FROM games WHERE igdb_id = 89390 ON CONFLICT (game_id, language_code) DO NOTHING;
