INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Floating Sandbox', 'This game is a realistic two-dimensional particle system, which uses mass-spring networks to simulate rigid bodies (such as ships) floating in water and exchanging heat with their surroundings. You can punch holes in an object, slice it, apply forces and heat to it, set it on fire, and smash it with bomb explosions. Once water starts rushing inside the object, it will start sinking and, if you''re lucky enough, it will start breaking up!' FROM games WHERE igdb_id = 167707 ON CONFLICT (game_id, language_code) DO NOTHING;
