INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Let''s Sing 2019: Mit Deutschen Hits!', 'Your song. Your voice. Your moment! Light up the speakers with the latest version of the singing game Let''s Sing. The fat playlist guarantees lots of fun for you and your friends. So choose your song and be the star of the next party, sing solo or together, among other things, German hits by artists such as Andreas Bourani with "Auf Andere Weg", Vincent Weiss with "Feuerwerk", Max Giesinger with 80 million" , Silbermond with "Leichtes Gepck", EFF with "Voice". International chart hits by artists such as Shawn Mendez with "There''s Nothing Holdin'' Me Back" and many other songs are available and of course legendary ones are allowed Karaoke classics like ABBA with "Mamma Mia" are not missing.' FROM games WHERE igdb_id = 253001 ON CONFLICT (game_id, language_code) DO NOTHING;
