INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Surfatron', 'You play as Dusty, a good-hearted but snarky now-sentient video game console from the 90''s. His clock speed isn''t what it used to be, but what he lacks for in megahertz he makes up for with experience and attitude! He''s trapped inside the Pixelverse - the space and time that exists between the hardware and his currently loaded game cartridge - left to battle the bugs and corruptions that the game developers left behind!' FROM games WHERE igdb_id = 103174 ON CONFLICT (game_id, language_code) DO NOTHING;
