INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Larkin building by Frank Lloyd Wright', 'The Larkin Building build by Frank Lloyd Wright in 1904 is one of the most famous office building off all time. It has been demolished in 1954 and there where no color picture of the building till now. In this VR experience you can walk through the building and explore the spaces, furniture and atmosphere. You can pick up photographs of the building and listen to music throughout the building.' FROM games WHERE igdb_id = 101272 ON CONFLICT (game_id, language_code) DO NOTHING;
