INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Director of Football', 'Football Director is a tough job. Team motivation, training, squad selection ¬ these are just a few of the things that have a direct effect on the result of the match. But the Director of Football does all this plus: take charge of sponsorship, stadium, balance sheets and making sure the team performs in the league.' FROM games WHERE igdb_id = 71856 ON CONFLICT (game_id, language_code) DO NOTHING;
