INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Amazing Grace: What Color is Your Attribute?', '“A holy night with no dawn, my dear...” You awaken in a strange town full of art, blanketed in snow, and enclosed by a massive wall. On Christmas, it all burns down—and the girl who loves it most rewinds time to the start of Advent. Find the truth in the loop and paint it on this canvas of a town!' FROM games WHERE igdb_id = 119321 ON CONFLICT (game_id, language_code) DO NOTHING;
