INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Illusion: A Tale of the Mind', 'Illusion is a puzzle exploration game set in the ambience of the early 1920’s Parisian cabaret. Step into the shoes of a young girl named Emma and live her adventures as she is trapped inside the mind of a mad man. Embark on her journey through the mind’s-eye of her captors, living in a fractured world of old memories and festering wounds, that paradoxically reveals itself to be also a place of great beauty and intrigue.' FROM games WHERE igdb_id = 103035 ON CONFLICT (game_id, language_code) DO NOTHING;
