INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meow Wars: Card Battle', 'Meow Wars is a cat themed card battle game with easy to learn mechanics and charming hand drawn characters. Battle your way through each challenger to reach Commander Catrat and free Claw Mountain from his iron fisted grip. Each stage introduces a new cat and card ability in a compelling feline filled story. Challenge your friends to a PVP duel or test your might against a global audience.' FROM games WHERE igdb_id = 108302 ON CONFLICT (game_id, language_code) DO NOTHING;
