INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('legend-of-the-tetrarchs', 117738, '2018-11-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co249s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ardb0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Legend of the Tetrarchs', 'The holy sword that sealed away an ominous power has been drawn out and darkness starts to spill out across the land, mutating people into monsters. The four Tetrarch heroes of ancient times will meet a new band of brave warriors to slash through the darkness with the light of courage! What will they find beyond the chaos? This is a full-fledged fantasy RPG with thrilling turn-based battles. Throw yourself into command battles with up to 10 allies and your own strategy using skill sets. The beautiful pixel animation and art aren''t just present in combats but also while you adventure around the expansive openworld or dungeons! Go on treasure hunting to boost your status, take on side quests and speed up battles to become the legendary new hero! A grand fantasy tale is ready for you to save the world!' FROM games WHERE igdb_id = 117738 ON CONFLICT (game_id, language_code) DO NOTHING;
