INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Elium: Prison Escape', 'Elium: Prison Escape is a realistic swordfighting action roguelite in a medieval setting. Play in First and 3rd Person view with shooter-like controls, in a challenging and unforgiving prison environment with the main goal of finding an escape. Take the role of Jarren Sorengar, a master swordsman seeing his days pass as a weary war prisoner. Time has come to meet fate, find an escape or die in the attempt.' FROM games WHERE igdb_id = 83953 ON CONFLICT (game_id, language_code) DO NOTHING;
