INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('globalmap-astro', 103944, '2018-06-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co41bh.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arht4.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GlobalMap Astro', 'GlobalMap Astro is a program for observing the Universe in 3D format. It is your guide in a three-dimensional model of the Universe. It allows you to see 1.6 million galaxies, over 6 million stars (up to 13th magnitude), as well as planets, comets, asteroids, artificial satellites, spaceports and cities of our planet. Among the most interesting features of the product - to view the lunar and solar eclipses, planetary motion simulation, launch Soyuz rocket from the Baikonur Cosmodrome. Here, in this program, you can not only enjoy space objects, but also learn new facts and astronomical characteristics about them. The program allows you to study astronomy with varying degrees of dedication. It is incredibly interesting for both children and adults.' FROM games WHERE igdb_id = 103944 ON CONFLICT (game_id, language_code) DO NOTHING;
