INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Project Lambda', 'Project Lambda a is a re-envisioning of Valve Software''s classic science fiction first person shooter, Half-Life. Powered by Unreal Engine 4, You will re-visit the inaugural role of Gordon Freeman and his memorable journey through the Black Mesa Research Facility. Expect detailed environments to explore, a huge cast of characters and experimental weaponry.' FROM games WHERE igdb_id = 117291 ON CONFLICT (game_id, language_code) DO NOTHING;
