INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tamagotchi On: Fairy ver.', 'The Tamagotchi On is a color-screened Tamagotchi, released on November 23, 2018 in Japan, and in the USA on July 28, 2019. It is the successor to the Tamagotchi m!x, having similar functions but with new features and characters, and the first color-screen Tamagotchi to be released in North America.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 230043 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
