INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Red Hot Ricochet', 'It''s high noon in this barren wasteland, and only one of you is making it out alive. Sure, you could try and shoot them right between the eyes - but where''s the fun in that? Red Hot Ricochet is an intense game of ricochet duels, and you''ll need wise shooting, lucky bounces, and a bit of triggernometry to win.' FROM games WHERE igdb_id = 83610 ON CONFLICT (game_id, language_code) DO NOTHING;
