INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Perspectrum', 'Perspectrum, an indie game developed by ProudMom Games, is a 2-D puzzle platformer for Windows, Mac, and Linux via Steam, Itch.io, and Game Jolt. Players take the role of the "Tall Stranger", a being who has awakened with the power to use ancient fountains to change the elements of the world. The stranger must use spirit fragments scattered throughout the various levels to bring the mountain back to life. The game will include an overworld and five dungeons, each introducing it''s own unique mechanic to help collect more spirit fragments.' FROM games WHERE igdb_id = 106613 ON CONFLICT (game_id, language_code) DO NOTHING;
