INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rune Stones Quest 2', 'Years of war have certainly left marks on the once booming country of the dwarves. There is nothing left but ruins, poverty is ruling people’s lives. But now that the war is over, the dwarves embark on a hopeful mission: they want to rebuild the ancient city and bring it back to its former glory! Get ready for a marvelous Match-3 adventure and help them to craft the protective rune stones!' FROM games WHERE igdb_id = 96401 ON CONFLICT (game_id, language_code) DO NOTHING;
