INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Holobunnies: The Bittersweet Adventure', 'Holobunnies is a challenging and rewarding side-scrolling adventure game that happens across every corner of the universe. You play as one of the Holobunnies, Danielle the witch, Leenox the hunter, Roméo the bard, Mephisto the ninja and Avril the catcher which are hologram brothers and sisters, living together aboard their very own starship. Explore planets, fight with vile and weird creatures, meet with special and peculiar people, collect treasures and collectibles and ultimately; find a new home for you and your hologram buddies. Share the fun of exploration and fighting with a friend (or foe?) in coop mode.' FROM games WHERE igdb_id = 28897 ON CONFLICT (game_id, language_code) DO NOTHING;
