INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Apartment', 'The Apartment is a small psychological thriller. Bizzare mix of first person detective adventure game, action and psychological horror with some interesting puzzles, all tied together with dark and heavy story where lines between reality and nightmare have no meaning anymore. It is not a pure horror and it''s not just a story adventure either.' FROM games WHERE igdb_id = 81900 ON CONFLICT (game_id, language_code) DO NOTHING;
