INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Subject', 'Can you survive the experiment? The Subject is a Sci-Fi horror game from DarkStone Digital. Play as a prisoner sold off to a deep-space testing facility. Navigate the maze-like complex and solve various puzzles while a strange creature hunts the next subject forced into its halls. You.' FROM games WHERE igdb_id = 105716 ON CONFLICT (game_id, language_code) DO NOTHING;
