INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '25 Cadre of Death', 'The dead city of Time Beach, in the American state of Misuri, generates a sense of fear and loneliness. This city and its districts are completely cut off from the real world. The main character is Caleb Ridus, having got there for not understandable reasons, it is necessary to understand what happened in this city.' FROM games WHERE igdb_id = 105635 ON CONFLICT (game_id, language_code) DO NOTHING;
