INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anime Music Quiz', 'Anime Music Quiz is a quiz game about anime music! Inspired by the popular “guess the opening/ending song” quizzes that are all about matching a set of anime songs to their anime, Anime Music Quiz takes these quizzes one step further! Thanks to the ever-expanding community-driven song database, an unlimited amount of unique quizzes can be generated. Furthermore you can add your MyAnimeList account to have your quizzes personalized by the anime you’ve watched, while still throwing in new and fresh anime for you to discover!' FROM games WHERE igdb_id = 131061 ON CONFLICT (game_id, language_code) DO NOTHING;
