INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Chikafag and Chika', 'The Chikafag, an amnesiac man who recently moved into the small sea side town of Uchiura, falls in love with a girl named Takami Chika he meets there. Chika falls for The Chikafag too and everything is alright in the world. ... That is, until someone decides they can''t allow their relationship to develop any further.' FROM games WHERE igdb_id = 165133 ON CONFLICT (game_id, language_code) DO NOTHING;
