INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Siberian Dawn', 'Siberian Dawn is an original, solo, digital card game that combines the core soul of a deck builder with the tactical power of a war game and the strategic challenge of crisis management. Take on various objective based Missions as you defend the Union against the dangers of the cult of the Dawn.' FROM games WHERE igdb_id = 107794 ON CONFLICT (game_id, language_code) DO NOTHING;
