INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('infinity--1', 110478, '2018-09-27', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/sc5iaw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Infinity', '"Infinity is a simple game. It has simple objectives, and a simple goal. The game features progressively harder levels. Each level builds upon the previous. Some levels feature verticality, while others have small platforms. The player must execute precise jumps, and movements in order to complete a level. However, what sets Infinity apart from other platformers, is the lack of checkpoints. Infinity does not feature saves, checkpoints or level selection. You simply play to complete all levels. We offer three gamemodes, Standard Play, Progressive Play, and Training. Standard Play is the 12 level experience. Players will play through 12 levels, all expanding upon different ideas, and introducing new challenges. Progressive Play is a single level that is challenging and quite lengthy. Training is a way for players to practice their skills in a safe environment."' FROM games WHERE igdb_id = 110478 ON CONFLICT (game_id, language_code) DO NOTHING;
