INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Just Beat Em Up : World of Fury', 'Just Beat Em Up : World of Fury is a "side-scrolling beat''em up" that brings you back to the golden age of arcade games. Fight alone or with a friend and beat up all your foes. Escape from the prison of the desert, chase after general Bombix and foil Iron Muscle''s evil schemes. You will face many dangers through thirty different levels, all accompanied by explosive sound tracks.' FROM games WHERE igdb_id = 108326 ON CONFLICT (game_id, language_code) DO NOTHING;
