INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Black Mirror: Bandersnatch', 'Black Mirror: Bandersnatch is an interactive movie in the Black Mirror series, produced by Netflix. The movie has a playable interface with which the player choose some of the character''s actions and end up with different endings based on your choices. The plot talks about a young man trying to be a game developer in the ZX Spectrum era, while gets around the inner functioning of the scene and tries to survive the choices the player makes.' FROM games WHERE igdb_id = 136096 ON CONFLICT (game_id, language_code) DO NOTHING;
