INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AeternoBlade II', 'Harness the AeternoBlade – and defy the abyss in this sequel to the fast-paced action/puzzle platformer. In AeternoBlade II, use the power of time itself to outwit your enemies and explore mysterious new dimensions. Jump between frenetic combat encounters and intriguing puzzle segments that require ingenious use of time.' FROM games WHERE igdb_id = 28079 ON CONFLICT (game_id, language_code) DO NOTHING;
