INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Daze', 'The world you’re about to experience Crafted by researching Multiple comatose patients real-life and Dreamworld events. No Matter where you come from or who you are, allow me to be the first to say: Welcome to Daze. A point&click game where unique minimalistic art style creates an unforgettable and atmospheric experience. The game is about a young 12 year’s old boy who lost his mother, now he is on his way to find her.' FROM games WHERE igdb_id = 112661 ON CONFLICT (game_id, language_code) DO NOTHING;
