INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('picnic--1', 88068, '2018-03-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobdcu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/mlm2ebqyvni4ddy00sdk.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Picnic', 'Picnic is a 3 dimensional labyrinth game. And this 3 dimensions are not only spatial: The first dimension is the visual dimension, a surreal digital labyrinth in which the user is awaking in the middle of a nightmare. Far away is a kind of bright green plastic hill, this seems to be, close to a strange phony star, the only colorful thing in the monochrome game world. On a wall is something written, inviting the user to go to the green hill, to the "picnic hill". On another wall: The user should listen carefully, THEY will show him/her the way. If the user is "listening carefully", THEY will "show you the way". And actually, if the user is searching a way through the visual labyrinth, THEY appear and THEY are telling something... It seems to be a story... about someone, who is planning to make (the game) picnic or even to have a picnic, but something happens... maybe something very scary... So the second dimension is the story labyrinth. While searching a way through the labyrinth...' FROM games WHERE igdb_id = 88068 ON CONFLICT (game_id, language_code) DO NOTHING;
