INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'SiIvaGunner: King for a Day Tournament - Playable Credits Minigame!!', 'SiIvaGunner: King for a Day Tournament - Playable Credits Minigame!! is a short game made for the SiIvaGunner: King for a Day Tournament which is based on the credits segment of Super Smash Bros. Melee, in which the player scores points by shooting down all the credits from the tournament. The game was released with the video "ONE FINAL ANNOUNCEMENT (for real this time)" alongside the album for the soundtrack for the event.' FROM games WHERE igdb_id = 326974 ON CONFLICT (game_id, language_code) DO NOTHING;
