INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('monastery--1', 342174, '2018-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9r3u.jpg', NULL, NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monastery', 'This is 2018’s assignment, a diabolical puzzle. You’re a monk who has forgotten where his cell is in the monastery, and who must walk the labyrinth in order to remember it. If you can find his room, you’ll find out what the assignment prompt is. I was a bit worried the students would be unable to find the prompt hidden in this one, but about half of them got there eventually. (The rest were expelled from the university.)
