INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Scent of Summer', 'This is a short story of a boy and girl in elementary school 6th grade in Japan. You can experience to go back home from school with a girlfriend who goes the same cram school in the early summer evening. Special things don''t happen but you can being with a girlfriend in a sentimental atmosphere of dusk.' FROM games WHERE igdb_id = 81983 ON CONFLICT (game_id, language_code) DO NOTHING;
