INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Russian AYE Horror', 'Russia, alternative to 2488, became the President Grudenen Tsar Pupin resigned for a long time, Russia was swallowed up in chaos, in search of supplies necessary for survival Sanya came to the village of Kuvandyk, there he went looking for a provincial reservation, but the building turned out to be the home of Valera''s grandfather and Sanya inside the building saw strange things - portraits of President Putin, terrible sounds and Sanya decided to quickly find supplies and leave the building.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 96887 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
