INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scenic Forest Valley', 'I created a detailed forest valley scene to be explored in first person as a walking sim. This project was an experiment using unreal engine 4 to achieve an overcast lighting look with some realistic forest assets. I wanted to create an immersive experience by letting the player explore the scene at their own pace, accompanied with ambient sounds and music.' FROM games WHERE igdb_id = 134250 ON CONFLICT (game_id, language_code) DO NOTHING;
