INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'An Aspie Life', 'One day your roommate Leaves for no reason. You’re left to face the outside world alone. But this can be both difficult and amazing when you have autism. This game recreates how some people with autism perceive the world. All forms of sound, graphics and interactions are intentional.' FROM games WHERE igdb_id = 83798 ON CONFLICT (game_id, language_code) DO NOTHING;
