INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '10S', '10S is a sports shmup with a light roguelike bent to it. After tennis-ing your way through a random wave of monsters, you''ll be asked to pick from one of three upgrades. There''s bosses to fight, oddly eerie music, and if you don''t like the look of the game you can hand-pick your own colour palette.' FROM games WHERE igdb_id = 134323 ON CONFLICT (game_id, language_code) DO NOTHING;
