INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dinosaurus Life VR', 'Dinosaurus Life VR is the world’s first Jurassic Safari Park (is it really ?). Discover an island full of famous dinosaurs such as Argentinosaurus, Stegosaurus, Pteranodon (even if it’s not a dinosaur), Tyrannosaurus, and so on. You can admire them, learn about them and interact with some of them.' FROM games WHERE igdb_id = 112711 ON CONFLICT (game_id, language_code) DO NOTHING;
