INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Martha Madison: Simple Machines Volume 1', 'Transform your room into a science lab and go bonkers with Martha Madison: Simple Machines Volume 1. Players, as virtual scientists, work alone or collaboratively with a partner to use screws, inclined planes and wedges to solve physics puzzles and challenges. Martha Madison, meerkat scientist and student mentor, is on-hand to guide players as they embark on science-filled, problem-solving adventures that bring classroom instruction to life.' FROM games WHERE igdb_id = 83957 ON CONFLICT (game_id, language_code) DO NOTHING;
