INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('martha-madison-optics', 83932, '2018-02-08', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobke3.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/l0rgekxlce5ceiryvcmd.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Martha Madison: Optics', 'Imagine transforming your room into an ancient temple full of optical wonder. With Martha Madison: Optics, students solve challenges based on topics such as reflection, refraction, and concave & convex lenses. Explore the free-play optics playground and create new playable levels in the game. Just like real-life scientists, you can work alone or collaboratively to experiment with different approaches. Players are free to make mistakes and try different paths. Martha Madison: Optics is part of a series of physical science games developed to enhance middle school science curriculum and improve outcomes by captivating students and making complex concepts meaningful. Every unit is aligned to standards, backed by research, incorporates best practices in teaching, and leverages innovative game design.' FROM games WHERE igdb_id = 83932 ON CONFLICT (game_id, language_code) DO NOTHING;
