INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('thrateon', 359095, '2018-03-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob4ez.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4zjv.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Thrateon', 'From the heart of the ruthless desert of Sistan, more ruthless creatures rise and turn to Zabol. There is no gate that can hinder them. There is no wall that can withstand them. Pishdad Shah is left defenseless. An army rushes from the south - it is Boras who comes to help. Boras drives back the demons, but Zabol is left in a burnt ruin. There is no place to stay. Boras takes the survivors to Jiroft, under the shade of the giant Gokran tree. But the danger still remains. The rebels cannot be controlled. Sistan needs tough men. Boras calls for fighting men. Mehrdad takes up a blade and joins Boras'' army. He receives a special mission to take a shipment to Zabol. But this is no ordinary journey. Behind the scenes, there is news...
