INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Tension', 'The Tension is a stealth-based puzzle horror game. It''s a game where the player can see the character from the top camera view and control it. The main mentality of the game taken from Alien Isolation. You will be controlling a kid who got kidnapped by aliens. You will be trying to escape from their mother ship.' FROM games WHERE igdb_id = 110764 ON CONFLICT (game_id, language_code) DO NOTHING;
