INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Railroad Operator', 'Let''s operate a train that makes you feel the Showa era! Current Japanese train maneuvering is the lever type, but in the past trains were operated with a mas-con handle and a brake lever. Its operation seems to be complicated, but as you repeat playing, it will lead to the "fun" inherent in railroad games. (Showa is the era of Japan and refers to the period from December 25, 1926 to January 7, 1989)' FROM games WHERE igdb_id = 89332 ON CONFLICT (game_id, language_code) DO NOTHING;
