INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Doodle God: Alchemy Jam', 'Imagine you''ve been given the chance to start everything over again, create your own planet, and fill it with living creatures, forests, rivers... Build roads and entire cities! Invent electricity and the internet! Think up music and the oatmeal cookie! Here you''ll find the dream constructor for any true Creator. Start with the basic elements — water, air, earth and fire — and create the world of your dreams!' FROM games WHERE igdb_id = 80911 ON CONFLICT (game_id, language_code) DO NOTHING;
