INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Coffee Crawl', 'The world has fallen asleep, and you''re among the few who are still awake. Choose your class, manage your resources, craft items, collect loot, work with other survivors, and survive to see the next dawn; in this unique blend of action RPG, survival, and roguelike.' FROM games WHERE igdb_id = 90311 ON CONFLICT (game_id, language_code) DO NOTHING;
