INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sega Pocket Club Manager', 'The popular football RPG from SEGA, Pocket Club Manager, now available in English for the first time on mobile devices! Based on the popular “Let’s Make a Professional Soccer Club” series, Pocket Club Manager has been designed from the ground up to be as close to the original series as possible, complete with the same cycle of club management, player training, finance management and football simulation.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 102430 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
