INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fantasy Realm: A Land Torn Asunder', 'Embark on an epic adventure, in which you must unite the survivors of a fantastical apocalypse and strike back against the greatest evil the world has ever known. Combining elements of classical turn-based and modern open-world roleplaying games, Fantasy Realm delivers a unique yet familiar experience, the likes of which you''ve never seen before.' FROM games WHERE igdb_id = 97278 ON CONFLICT (game_id, language_code) DO NOTHING;
