INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('animated-jigsaws-japanese-women', 110734, '2018-10-04', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co570e.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar9yy.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animated Jigsaws: Japanese Women', 'Complete moving jigsaw puzzles alone or team up with friends and finish them together! Animated Jigsaws: Japanese Women contains short videos as jigsaw puzzles that are pieced together to reveal beautiful ladies. The video puzzles capture 10 beautiful Japanese ladies wearing traditional kimono and yukata clothes in various locations such Kyoto City, by a lake, and relaxing in a hot spring bath. An easy-to-use interface such as separating edge and inner pieces makes solving puzzles fun and relaxing. Tackle the puzzles by yourself, or team up with friends and solve them together. Features: Solve puzzles with friends in multiplayer for up to 4 players Easy-to-play traditional jigsaw puzzle Selection of three background colors 3 sizes for each puzzle: 60, 120 and 240 pieces Saves time spent completing each puzzle and each size Separate edge and inner pieces Each piece snaps into place for stress-free experience Ability to snap individual pieces together Save a puzzle half way and continue later Selection of traditional Japanese music to choose from' FROM games WHERE igdb_id = 110734 ON CONFLICT (game_id, language_code) DO NOTHING;
