INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brendan Keogh''s Putting Challenge', 'Brendan Keogh''s Putting Challenge is a Pico-8 golf game about the parts of golf that other videogames cut out. Put the ball on the tee yourself. After hitting the ball, manually walk to where the ball went before you hit it again. If the ball goes in the water, put down another ball! Remove your ball from the hole before moving on to the next hole. If you run out of balls, return to the Pro Shop to get more balls. This is a golf game with unprecedented interactivity!!' FROM games WHERE igdb_id = 134869 ON CONFLICT (game_id, language_code) DO NOTHING;
