INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Relic Raiders', 'Relic Raiders is a top-down, team-based fighting game with a strong emphasis on tactical strategy and high-speed combat. Players band together in two teams (in either 2v2 or 4v4 matches) and are set loose on an asymmetrical map where they battle for control of the map''s relic. Only one team can escape with the relic so strong team coordination, intelligent strategy, and mastery of character abilities are the keys to victory.' FROM games WHERE igdb_id = 70986 ON CONFLICT (game_id, language_code) DO NOTHING;
