INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Panzer Strategy', 'Panzer Strategy: Blitzkrieg is a historical wargame on Unreal Engine where like in re­al life you can adapt your units to any objective using equipments and skills. Moreover you can make your tactics even more flexible with skills and abilities of your HQ and the HQ Commander! And all of these combined with UnrealEn­gine with the free camera mode allow you to ch­eck the whole scene fr­om the aerial view or fa­ll deep into act­ion with the close-up fu­nction!' FROM games WHERE igdb_id = 83612 ON CONFLICT (game_id, language_code) DO NOTHING;
