INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Housewarming Gift', 'Remmie''s bestie Nunu invited them both to her friend Mira''s housewarming party. Not only is Remmie waking up hours late, completely forgotten all about the thing until just now. Nunu isn''t responding to her messages, so maybe she''s there already? With only one way to find out, Remmie ends up leaving and thinks to herself.' FROM games WHERE igdb_id = 237535 ON CONFLICT (game_id, language_code) DO NOTHING;
