INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mechsprofit', 'A mech tycoon simulator game. Mechsprofit takes place in the beginning of a mech industry revolution, where giant mechanized robots are as ubiquitous as cars nowadays. You, as a novice mech factory owner have to produce (profitable) commercial mechs in order to keep your factory running. Research the expansive tech tree, analyze the market, assemble the perfect mech, achieve MECHSimum PROFIT!' FROM games WHERE igdb_id = 96842 ON CONFLICT (game_id, language_code) DO NOTHING;
