INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dream Match Tennis VR', 'The first person viewpoint and simulated physics give the sensation of truly playing tennis. The experience of holding a racket and hitting a ball -- so difficult to capture on a TV screen in the past -- has been fully realized in VR. The movement, rotation, angle, friction, and bounce of the racket and ball are fully simulated, and you can even freely perform things like topspin and slices, which cause the ball to spin.' FROM games WHERE igdb_id = 105507 ON CONFLICT (game_id, language_code) DO NOTHING;
