INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('fritz-chess-16-steam-edition', 95148, '2018-04-03', NULL, NULL, 'https://images.igdb.com/igdb/image/upload/t_1080p/ec8xemu6yswhyfzogfqm.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fritz Chess 16: Steam Edition', 'When is chess the most enjoyable? When you win! When Fritz entered his first tournaments some 25 years ago, humans still had a real chance of taking the engine down. Only a few years down the line, Fritz was already beating grandmasters left, right and center, but ever since his 4:2 victory over Kramnik in 2006, Fritz has been considered unbeatable. Who would want to play against him? In the case of Fritz 16, however, playing against an engine is now once again the very definition of fun! A host of features, including "Assisted Analysis", which gives you discreet visual hints as you move, and emoticons, which show Fritz’s mood, are there to help you. Even with little knowledge of chess, you can enjoy many an exciting game, and more importantly, victory, against Fritz. If things don’t work out, Fritz 16 shows you the combinations you might have missed directly after the game with the handy “Tactical Analysis” function, or you can dive right into "Easy Play" calculation training to hone your skills. Fritz doesn’t come up short when it comes to playing strength either: the new multiprocessor engine was developed by star programmer Vas Rajlich ("Rybka") and is up there with the global elite.' FROM games WHERE igdb_id = 95148 ON CONFLICT (game_id, language_code) DO NOTHING;
