INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astrokings', 'Clash with rivals in powerful cosmic spaceship battles, manage futuristic resources, and build planetary facilities on countless worlds, an epic planetary colonization adventure awaits! Build your own space starship fleet command, customize it with powerful weapons, and command it either solo or with an alliance team to conquer the galaxy! Bid to become the absolute galactic imperator in this epic, sci-fi real-time strategy multiplayer saga.' FROM games WHERE igdb_id = 109915 ON CONFLICT (game_id, language_code) DO NOTHING;
