INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Toy Stunt Bike: Tiptop''s Trials', 'Toy Stunt Bike is a 3D, action-packed, micro-sized motorbike trials game. Guide Tiptop the chimpanzee across thirty-six tracks set in a variety of household locations. Leap over toasters, make massive jumps onto garden chairs, use laptops as ramps and perform crazy stunts. Silky smooth 60fps gameplay in every mode. Thirty-six tracks to race + secrets. Compete worldwide with online leaderboards. Spectacular bike stunts and crashes. Ideal for handheld, short burst play. Stunning soundtrack by Waterflame.' FROM games WHERE igdb_id = 106979 ON CONFLICT (game_id, language_code) DO NOTHING;
