INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blasted Road Terror', 'Blasted Road Terror is real-time tactical looter in post apocalyptic setting. Command mighty warcrawler and manage squadron of vehicles in order to get unseen riches of the world and reach immortal glory. You will collect mighty arctifacts during your journey, enlarge your vehicle squadron so you can always pick right one for the job, rebuild your home base, make new friends and discover terrible enemies.' FROM games WHERE igdb_id = 34658 ON CONFLICT (game_id, language_code) DO NOTHING;
