INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Lettergraf', 'Combining elements from popular classic games, with a unique puzzle mechanic fusing Rubik''s cube rotation and crossword game, this is not your typical word game. Move blocks of letters and shift/rotate letters to form target words. Think out of the box to solve more than a hundred puzzles. Calm and relaxing music, with absolutely no timer. Relax and play at your own pace.' FROM games WHERE igdb_id = 174375 ON CONFLICT (game_id, language_code) DO NOTHING;
