INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Progetto Ustica', 'Progetto Ustica is a serious game that aims at keeping alive the memory of one of the most tragic events in recent Italian history. It is a short exploratory experience created for PC/MAC and supporting Oculus Rift VR and HTC Vive.' FROM games WHERE igdb_id = 90717 ON CONFLICT (game_id, language_code) DO NOTHING;
