INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Need for Spirit: Drink & Drive Simulator', 'Abysmal roads aside, the biggest enemy will be your very own addiction to the booze you’re transporting. Potholes seem harmless after you’ve transformed into an insatiable drunkard which suddenly thinks that he’s got the off-road skills to take as many shortcuts as needed.' FROM games WHERE igdb_id = 107819 ON CONFLICT (game_id, language_code) DO NOTHING;
