INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Zap Zap Zombie Cats', 'You are one of the few survivors of a zombie cat-pocalypse. With only your wits, your weapons, and a few turrets, you must defend yourself from the hordes of zombie-cats that come at night. Grenade, blast, shoot, heal, and place traps to survive each wave until safety comes with the sunlight.' FROM games WHERE igdb_id = 99065 ON CONFLICT (game_id, language_code) DO NOTHING;
