INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Merrily Perilly', 'Merrily Perilly is a game about crisis. You play as Perry, a severely dehydrated man who stumbles into a remote village in search of help, but the inhabitants respond with strange detachment to your trouble. You may think that the nearby fountain is a safe means to quench your dire thirst, but you would soon find yourself in search of aid for a snake bite. And before you know it, you will be chased by bees, fending off bears, cursed by gypsies, and most likely on fire.' FROM games WHERE igdb_id = 104028 ON CONFLICT (game_id, language_code) DO NOTHING;
