INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bendy in Nightmare Run', 'Bendy In Nightmare Run is an action-packed ‘boss runner’ for your Android device. Play as Bendy, Boris the Wolf and Alice Angel as you swipe to jump, dash and counter-attack four of the largest, nastiest bullies ever depicted in the classic 1930''s cartoons of Joey Drew Studios. The action never stops as you fend off enemies, avoid obstacles and navigate your way through pirate ships, city streets, a junkyard and a not so quiet library.' FROM games WHERE igdb_id = 90246 ON CONFLICT (game_id, language_code) DO NOTHING;
