INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('howlville-the-dark-past', 99084, '2018-05-11', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co43e2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arelw.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Howlville: The Dark Past', 'Many years ago an artifact was found in one of the mines near the small town of Howlville. The government asked scientists to examine it. Dr. Joseph was one of those scientists. Strange events began to happen in the underground lab, and something went wrong, causing a strong earthquake. The experiment was halted and classified, while the territory of the town was closed. Nobody knew what had happened to Joseph, and he was listed as a missing person. Fifteen years later his daughter Rachel is on the verge of solving the mystery, but somebody is doing everything possible to keep her from succeeding. Rachel is institutionalized in a secret mental hospital. She starts having horrible nightmares in which her father is pleading for her help and talking about a looming catastrophe. She manages to escape. Fleeing from the police, she reaches Howlville.' FROM games WHERE igdb_id = 99084 ON CONFLICT (game_id, language_code) DO NOTHING;
