INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prey: Digital Deluxe Edition', 'Prey is a first-person sci-fi action game from Arkane Studios, the award-winning creators of the Dishonored franchise. Known for their creative gameplay, distinctive worlds, and immersive stories, Arkane reimagines this franchise from the ground up, with an added psychological twist. Prey Digital Deluxe includes Prey, Prey: Mooncrash DLC, and the free Mooncrash update, Prey: Typhon Hunter.' FROM games WHERE igdb_id = 118686 ON CONFLICT (game_id, language_code) DO NOTHING;
