INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Voxel Shot for Nintendo Switch', 'Voxel Shot is a simple pick up and play action game set in an adorably quirky world of toys where you and your friends beat up zombies (and each other!) using a variety of different weapons. A world ravaged by zombified toys infected with a mysterious virus. Day after day, the toys fight for control of the remaining resources. Defeat unique zombies with a variety of weapons at your disposal! There are even cars and motorcycles to ride around in each stage!' FROM games WHERE igdb_id = 105608 ON CONFLICT (game_id, language_code) DO NOTHING;
