INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Far Cry 5: Gold Edition', 'Want even more Far Cry 5? Upgrade to the Gold Edition and get a Season Pass subscription plus immediate access to all Deluxe Edition content. Also available—SteelBook Gold Edition (physical only), featuring a collectible SteelBook case. Gold Edition includes: Day 1 Exclusive—MBP Sniper Rifle, Far Cry 5 Season Pass subscription, .44 Magnum handgun with unique skin, AR-C assault rifle with unique skin, Ace Pilot Pack (includes helicopter, gun skin, and Aerial Force outfit), Big-Game Hunter Pack (includes ATV, bow, and Big-Game Hunter outfit) Additional Chaos Pack, and Explosive Pack.' FROM games WHERE igdb_id = 53011 ON CONFLICT (game_id, language_code) DO NOTHING;
