INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monkey King: Master of the Clouds', 'A huge Japanese coin-op hit developed by HOT-B in 1989, the game was later renamed Cloud Master when released outside Japan on the Sega Master System. This upgraded release of the original arcade version includes HD ready elements by developer Starfish-SD, the company formed by the original HOT-B development team. For the first time, live online leaderboards will add a worldwide competitive quality to the game not possible before.' FROM games WHERE igdb_id = 103248 ON CONFLICT (game_id, language_code) DO NOTHING;
