INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RPG Maker MV Trinity', 'An epic journey begins… with YOU! Become a master game developer with RPG Maker MV Trinity. With an arsenal of tools at your fingertips create elaborate, exciting, and memorable video games straight from your console! Then, share your adventures online with other players, who can enjoy your epic chronicles! The possibilities are endless with the latest and greatest RPG Maker software. With hundreds of assets and an infinite number of ways to create your game, turn your dream tale into the next greatest video game.' FROM games WHERE igdb_id = 136722 ON CONFLICT (game_id, language_code) DO NOTHING;
