INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Midnight Deluxe', 'Use your controller or touch screen controls to launch Midnight into the night sky, but watch out! The world of Midnight is a dangerous one thanks to the likes of spikes, circular saws and plenty of other dangerous objects. And even if you do manage to get Midnight into the safe zone to advance to the next level, there’s the added challenge of trying to complete each level in the least amount of shots as possible to get all three Stars.' FROM games WHERE igdb_id = 89495 ON CONFLICT (game_id, language_code) DO NOTHING;
